#!/usr/bin/env perl
# -*- coding: utf-8 -*-
use strict;
use warnings;
use Getopt::Long qw(GetOptions);
use File::Basename qw(dirname);
use File::Path qw(make_path);
use Cwd qw(abs_path);
use IO::Handle;

STDOUT->autoflush(1);
STDERR->autoflush(1);

# ============================================================
# Script:
#   run_discordant_reads.pl
#
# Purpose:
#   Extract and cluster deletion-like discordant read-pair evidence
#   from SAMPLE.target.bam.
#
# Pipeline logic:
#   1. Input BAM is already SAMPLE.target.bam generated by
#      extract_target_bam.pl.
#   2. The target BAM already contains HCM core genes plus flank.
#   3. Therefore, this script does NOT read:
#        HCM_CORE_GENE_LIST
#        REFSEQ_MANE_SELECT_GENE_TXT
#        TARGET_REGION_FLANK
#        REF_FASTA_INDEX
#   4. This script scans the whole target BAM directly.
#   5. It keeps intrachromosomal read pairs with large insert size.
#   6. To avoid double counting one fragment twice, only TLEN > 0
#      records are retained.
#   7. If FILTER_DELETION_ORIENTATION=1, only deletion-like FR
#      orientation is retained.
#
# Required command-line arguments:
#   --config
#   --bam
#   --sample
#   --out
#
# Required config parameters:
#   SAMTOOLS
#   MIN_MAPQ
#   EXCLUDE_DUPLICATES
#   MIN_DISCORDANT_INSERT_SIZE
#   MIN_DISCORDANT_READS
#   DISCORDANT_CLUSTER_DISTANCE
#   FILTER_DELETION_ORIENTATION
#   DISCORDANT_READ_THREADS
#
# Main output:
#   --out
#     PASS discordant clusters only.
#
# Derived outputs:
#   *.all_clusters.tsv
#   *.failed_clusters.tsv
#   *.supporting_pairs.tsv
#   *.raw_pairs.tsv
#
# Notes:
#   Gene/exon annotation should be performed later by
#   annotate_candidates.pl.
# ============================================================

my $config;
my $bam;
my $sample;
my $out;
my $help = 0;

GetOptions(
    "config=s" => \$config,
    "conf=s"   => \$config,
    "bam=s"    => \$bam,
    "sample=s" => \$sample,
    "out=s"    => \$out,
    "help"     => \$help,
) or die usage();

if ($help) {
    print usage();
    exit 0;
}

die usage()
    unless defined $config && $config ne ""
        && defined $bam    && $bam    ne ""
        && defined $sample && $sample ne ""
        && defined $out    && $out    ne "";

# ------------------------------------------------------------
# Validate runtime I/O
# ------------------------------------------------------------
$config = abs_path($config) if -e $config;
die "[ERROR] Config file not found: $config\n"
    unless defined $config && -s $config;
die "[ERROR] Config path must be absolute after resolution: $config\n"
    unless $config =~ m{^/};

$bam = abs_path($bam) if -e $bam;
die "[ERROR] BAM file not found: $bam\n"
    unless defined $bam && -s $bam;
die "[ERROR] BAM path must be absolute after resolution: $bam\n"
    unless $bam =~ m{^/};
die "[ERROR] BAM file must end with .bam: $bam\n"
    unless $bam =~ /\.bam$/i;

check_bam_index($bam);

die "[ERROR] Invalid sample name: $sample\n"
  . "        Sample name can only contain letters, numbers, dot, underscore and hyphen.\n"
    unless $sample =~ /^[A-Za-z0-9_.-]+$/;

die "[ERROR] Output path must be absolute: $out\n"
    unless defined $out && $out =~ m{^/};

my $outdir = dirname($out);
make_path($outdir) unless -d $outdir;
die "[ERROR] Cannot create output directory: $outdir\n"
    unless -d $outdir;

# ------------------------------------------------------------
# Read config
# ------------------------------------------------------------
my %CONF = read_config($config);

for my $removed_key (qw/
    ANALYZE_CORE_GENES_ONLY
    CANDIDATE_BAM_FLANK
/) {
    if (exists $CONF{$removed_key}) {
        die "[ERROR] $removed_key has been removed from the HCMExonDel workflow.\n"
          . "        The input BAM for run_discordant_reads.pl should already be SAMPLE.target.bam.\n"
          . "        Please delete $removed_key from the config file.\n";
    }
}

my $samtools = get_conf_required(\%CONF, "SAMTOOLS");
check_executable($samtools, "SAMTOOLS");

my $min_mapq = get_conf_required(\%CONF, "MIN_MAPQ");
my $exclude_duplicates = get_conf_required(\%CONF, "EXCLUDE_DUPLICATES");
my $min_insert_size = get_conf_required(\%CONF, "MIN_DISCORDANT_INSERT_SIZE");
my $min_support_reads = get_conf_required(\%CONF, "MIN_DISCORDANT_READS");
my $cluster_distance = get_conf_required(\%CONF, "DISCORDANT_CLUSTER_DISTANCE");
my $filter_deletion_orientation = get_conf_required(\%CONF, "FILTER_DELETION_ORIENTATION");
my $threads = get_conf_required(\%CONF, "DISCORDANT_READ_THREADS");

validate_nonnegative_integer("MIN_MAPQ", $min_mapq);
validate_bool_01("EXCLUDE_DUPLICATES", $exclude_duplicates);
validate_positive_integer("MIN_DISCORDANT_INSERT_SIZE", $min_insert_size);
validate_positive_integer("MIN_DISCORDANT_READS", $min_support_reads);
validate_nonnegative_integer("DISCORDANT_CLUSTER_DISTANCE", $cluster_distance);
validate_bool_01("FILTER_DELETION_ORIENTATION", $filter_deletion_orientation);
validate_positive_integer("DISCORDANT_READ_THREADS", $threads);

# ------------------------------------------------------------
# Output files
# ------------------------------------------------------------
my $raw_pairs_out    = derive_raw_pairs_outfile($out);
my $all_cluster_out  = derive_all_clusters_outfile($out);
my $failed_out       = derive_failed_clusters_outfile($out);
my $support_pairs_out = derive_supporting_pairs_outfile($out);

print STDERR "[INFO] Discordant read-pair analysis started\n";
print STDERR "[INFO] Config: $config\n";
print STDERR "[INFO] Sample: $sample\n";
print STDERR "[INFO] BAM: $bam\n";
print STDERR "[INFO] PASS cluster output: $out\n";
print STDERR "[INFO] All cluster output: $all_cluster_out\n";
print STDERR "[INFO] Failed cluster output: $failed_out\n";
print STDERR "[INFO] Supporting pairs output: $support_pairs_out\n";
print STDERR "[INFO] Raw pairs output: $raw_pairs_out\n";
print STDERR "[INFO] SAMTOOLS: $samtools\n";
print STDERR "[INFO] MIN_MAPQ: $min_mapq\n";
print STDERR "[INFO] EXCLUDE_DUPLICATES: $exclude_duplicates\n";
print STDERR "[INFO] MIN_DISCORDANT_INSERT_SIZE: $min_insert_size\n";
print STDERR "[INFO] MIN_DISCORDANT_READS: $min_support_reads\n";
print STDERR "[INFO] DISCORDANT_CLUSTER_DISTANCE: $cluster_distance\n";
print STDERR "[INFO] FILTER_DELETION_ORIENTATION: $filter_deletion_orientation\n";
print STDERR "[INFO] DISCORDANT_READ_THREADS: $threads\n";

# ------------------------------------------------------------
# Extract discordant pairs
# ------------------------------------------------------------
my ($pairs_ref, $stats_ref) = extract_discordant_pairs(
    samtools                    => $samtools,
    bam                         => $bam,
    sample                      => $sample,
    min_mapq                    => $min_mapq,
    exclude_duplicates          => $exclude_duplicates,
    min_insert_size             => $min_insert_size,
    filter_deletion_orientation => $filter_deletion_orientation,
    threads                     => $threads,
    raw_pairs_out               => $raw_pairs_out,
);

my @pairs = @{$pairs_ref};

print STDERR "[INFO] Total SAM records after samtools filtering: $stats_ref->{total_records}\n";
print STDERR "[INFO] Candidate pairs before final filters: $stats_ref->{candidate_pairs}\n";
print STDERR "[INFO] Discordant pairs written: " . scalar(@pairs) . "\n";
print STDERR "[INFO] Skipped bad SAM records: $stats_ref->{skipped_bad_sam}\n";
print STDERR "[INFO] Skipped by flag: $stats_ref->{skipped_flag}\n";
print STDERR "[INFO] Skipped by mate chromosome: $stats_ref->{skipped_mate_chrom}\n";
print STDERR "[INFO] Skipped by TLEN sign: $stats_ref->{skipped_tlen_sign}\n";
print STDERR "[INFO] Skipped by insert size: $stats_ref->{skipped_insert_size}\n";
print STDERR "[INFO] Skipped by orientation: $stats_ref->{skipped_orientation}\n";
print STDERR "[INFO] Skipped by invalid interval: $stats_ref->{skipped_invalid_interval}\n";
print STDERR "[INFO] Skipped duplicated pair records: $stats_ref->{skipped_duplicate_pair}\n";

# ------------------------------------------------------------
# Cluster discordant pairs
# ------------------------------------------------------------
my @clusters = cluster_discordant_pairs(
    pairs_ref        => \@pairs,
    cluster_distance => $cluster_distance,
);

classify_clusters(
    clusters_ref      => \@clusters,
    min_support_reads => $min_support_reads,
);

# ------------------------------------------------------------
# Write outputs
# ------------------------------------------------------------
write_cluster_summary(
    clusters_ref => \@clusters,
    output       => $all_cluster_out,
    mode         => "All",
);

write_cluster_summary(
    clusters_ref => \@clusters,
    output       => $out,
    mode         => "Pass",
);

write_cluster_summary(
    clusters_ref => \@clusters,
    output       => $failed_out,
    mode         => "Failed",
);

write_supporting_pairs(
    clusters_ref => \@clusters,
    output       => $support_pairs_out,
);

my $pass_count = scalar(grep { $_->{Cluster_Status} eq "Pass" } @clusters);
my $failed_count = scalar(@clusters) - $pass_count;

print STDERR "[INFO] Discordant read-pair analysis finished\n";
print STDERR "[INFO] Total clusters: " . scalar(@clusters) . "\n";
print STDERR "[INFO] PASS clusters: $pass_count\n";
print STDERR "[INFO] Failed clusters: $failed_count\n";
print STDERR "[INFO] PASS cluster output: $out\n";
print STDERR "[INFO] All cluster output: $all_cluster_out\n";
print STDERR "[INFO] Failed cluster output: $failed_out\n";
print STDERR "[INFO] Supporting pairs output: $support_pairs_out\n";
print STDERR "[INFO] Raw pairs output: $raw_pairs_out\n";

exit 0;

# ============================================================
# Extract discordant pairs
# ============================================================

sub extract_discordant_pairs {
    my %args = @_;

    my $samtools = $args{samtools};
    my $bam = $args{bam};
    my $sample = $args{sample};
    my $min_mapq = $args{min_mapq};
    my $exclude_duplicates = $args{exclude_duplicates};
    my $min_insert_size = $args{min_insert_size};
    my $filter_deletion_orientation = $args{filter_deletion_orientation};
    my $threads = $args{threads};
    my $raw_pairs_out = $args{raw_pairs_out};

    # Require:
    #   0x1 = paired-end read
    my $require_flag = 1;

    # Exclude:
    #   0x4   read unmapped
    #   0x8   mate unmapped
    #   0x100 secondary alignment
    #   0x200 QC fail
    #   0x800 supplementary alignment
    #
    # Duplicate reads are excluded only when EXCLUDE_DUPLICATES=1.
    my $exclude_flag = 4 + 8 + 256 + 512 + 2048;
    $exclude_flag += 1024 if $exclude_duplicates == 1;

    my @cmd = (
        $samtools, "view",
        "-@", $threads,
        "-f", $require_flag,
        "-F", $exclude_flag,
        "-q", $min_mapq,
        $bam,
    );

    print STDERR "[CMD] ", join(" ", map { shell_quote($_) } @cmd), "\n";

    open my $RAW, ">", $raw_pairs_out
        or die "[ERROR] Cannot write raw discordant pair output: $raw_pairs_out\n";

    my @raw_header = qw(
        Sample
        Read_Name
        Flag
        Chrom
        Read_Start
        Read_End
        Mate_Chrom
        Mate_Start
        TLEN
        Insert_Size
        MAPQ
        CIGAR
        Read_Strand
        Mate_Strand
        Pair_Orientation
        Left_Breakpoint
        Right_Breakpoint
        SV_Chrom
        SV_Start
        SV_End
        SV_Length
        Pair_Key
    );

    print $RAW join("\t", @raw_header), "\n";

    open my $SAM, "-|", @cmd
        or die "[ERROR] Failed to run samtools view on BAM: $bam\n";

    my @pairs;
    my %seen_pair;

    my %stats = (
        total_records            => 0,
        candidate_pairs          => 0,
        skipped_bad_sam          => 0,
        skipped_flag             => 0,
        skipped_mate_chrom       => 0,
        skipped_tlen_sign        => 0,
        skipped_insert_size      => 0,
        skipped_orientation      => 0,
        skipped_invalid_interval => 0,
        skipped_duplicate_pair   => 0,
    );

    while (my $line = <$SAM>) {
        chomp $line;
        next if $line =~ /^\s*$/;

        $stats{total_records}++;

        my @f = split /\t/, $line;
        unless (@f >= 11) {
            $stats{skipped_bad_sam}++;
            next;
        }

        my ($qname, $flag, $rname, $pos, $mapq, $cigar, $rnext, $pnext, $tlen) = @f[0 .. 8];

        unless (
            defined $qname && $qname ne ""
            && defined $flag && $flag =~ /^\d+$/
            && defined $rname && $rname ne "*" && $rname ne ""
            && defined $pos && $pos =~ /^\d+$/ && $pos >= 1
            && defined $mapq && $mapq =~ /^\d+$/ && $mapq >= $min_mapq
            && defined $cigar && $cigar ne "*"
            && defined $rnext && $rnext ne "*" && $rnext ne ""
            && defined $pnext && $pnext =~ /^\d+$/ && $pnext >= 1
            && defined $tlen && $tlen =~ /^-?\d+$/
        ) {
            $stats{skipped_bad_sam}++;
            next;
        }

        unless (
            is_paired($flag)
            && !is_unmapped($flag)
            && !is_mate_unmapped($flag)
            && !is_secondary($flag)
            && !is_supplementary($flag)
        ) {
            $stats{skipped_flag}++;
            next;
        }

        if ($exclude_duplicates == 1 && is_duplicate($flag)) {
            $stats{skipped_flag}++;
            next;
        }

        my $mate_chr = $rnext eq "=" ? $rname : $rnext;

        unless ($mate_chr eq $rname) {
            $stats{skipped_mate_chrom}++;
            next;
        }

        # Keep only one side of the read pair.
        # In standard coordinate-sorted paired-end BAM, TLEN > 0
        # corresponds to the leftmost segment.
        if ($tlen <= 0) {
            $stats{skipped_tlen_sign}++;
            next;
        }

        my $insert_size = abs($tlen);

        if ($insert_size < $min_insert_size) {
            $stats{skipped_insert_size}++;
            next;
        }

        my $read_ref_len = cigar_ref_length($cigar);
        unless ($read_ref_len > 0) {
            $stats{skipped_bad_sam}++;
            next;
        }

        my $read_start = $pos;
        my $read_end = $pos + $read_ref_len - 1;
        my $mate_start = $pnext;

        my $read_strand = is_reverse($flag) ? "-" : "+";
        my $mate_strand = is_mate_reverse($flag) ? "-" : "+";
        my $pair_orientation = get_pair_orientation($flag);

        if ($filter_deletion_orientation == 1) {
            unless (is_deletion_like_orientation($flag)) {
                $stats{skipped_orientation}++;
                next;
            }
        }

        # Because TLEN > 0 is retained, this record is expected to be
        # the left segment. The deletion-like interval is approximated
        # by the inner gap between the left read end and the mate start.
        my $left_breakpoint = $read_end;
        my $right_breakpoint = $mate_start;
        my $sv_start = $left_breakpoint + 1;
        my $sv_end = $right_breakpoint - 1;

        unless ($sv_start <= $sv_end) {
            $stats{skipped_invalid_interval}++;
            next;
        }

        my $sv_length = $sv_end - $sv_start + 1;

        my $pair_key = join("|",
            $sample,
            $qname,
            $rname,
            $read_start,
            $read_end,
            $mate_chr,
            $mate_start,
            $insert_size,
        );

        if ($seen_pair{$pair_key}++) {
            $stats{skipped_duplicate_pair}++;
            next;
        }

        $stats{candidate_pairs}++;

        my %pair = (
            Sample           => $sample,
            Read_Name        => $qname,
            Flag             => $flag,
            Chrom            => $rname,
            Read_Start       => $read_start,
            Read_End         => $read_end,
            Mate_Chrom       => $mate_chr,
            Mate_Start       => $mate_start,
            TLEN             => $tlen,
            Insert_Size      => $insert_size,
            MAPQ             => $mapq,
            CIGAR            => $cigar,
            Read_Strand      => $read_strand,
            Mate_Strand      => $mate_strand,
            Pair_Orientation => $pair_orientation,
            Left_Breakpoint  => $left_breakpoint,
            Right_Breakpoint => $right_breakpoint,
            SV_Chrom         => $rname,
            SV_Start         => $sv_start,
            SV_End           => $sv_end,
            SV_Length        => $sv_length,
            Pair_Key         => $pair_key,
        );

        print $RAW join("\t", map { defined $pair{$_} ? $pair{$_} : "NA" } @raw_header), "\n";

        push @pairs, \%pair;
    }

    close $SAM
        or die "[ERROR] samtools view command failed for BAM: $bam\n";

    close $RAW;

    return (\@pairs, \%stats);
}

# ============================================================
# Clustering
# ============================================================

sub cluster_discordant_pairs {
    my %args = @_;

    my @pairs = @{ $args{pairs_ref} };
    my $cluster_distance = $args{cluster_distance};

    return () unless @pairs;

    @pairs = sort {
        chrom_order_key($a->{SV_Chrom}) cmp chrom_order_key($b->{SV_Chrom})
            || $a->{SV_Start} <=> $b->{SV_Start}
            || $a->{SV_End} <=> $b->{SV_End}
            || $a->{Read_Name} cmp $b->{Read_Name}
    } @pairs;

    my @clusters;
    my @current;

    for my $pair (@pairs) {
        if (!@current) {
            @current = ($pair);
            next;
        }

        my $current_chr = $current[0]->{SV_Chrom};

        if ($pair->{SV_Chrom} ne $current_chr) {
            push @clusters, build_cluster(\@current);
            @current = ($pair);
            next;
        }

        my $median_start = int_median(map { $_->{SV_Start} } @current);
        my $median_end   = int_median(map { $_->{SV_End} } @current);

        if (
            abs($pair->{SV_Start} - $median_start) <= $cluster_distance
            && abs($pair->{SV_End} - $median_end) <= $cluster_distance
        ) {
            push @current, $pair;
        } else {
            push @clusters, build_cluster(\@current);
            @current = ($pair);
        }
    }

    push @clusters, build_cluster(\@current) if @current;

    for my $i (0 .. $#clusters) {
        my $cluster_id = sprintf("DR_CLUSTER_%06d", $i + 1);
        $clusters[$i]->{Cluster_ID} = $cluster_id;

        for my $pair (@{ $clusters[$i]->{pairs} }) {
            $pair->{Cluster_ID} = $cluster_id;
        }
    }

    return @clusters;
}

sub build_cluster {
    my ($pairs_ref) = @_;

    my @pairs = @{$pairs_ref};

    die "[ERROR] build_cluster received empty pair list\n"
        unless @pairs;

    my @sv_starts = map { $_->{SV_Start} } @pairs;
    my @sv_ends   = map { $_->{SV_End} } @pairs;
    my @sv_lengths = map { $_->{SV_Length} } @pairs;
    my @insert_sizes = map { $_->{Insert_Size} } @pairs;
    my @left_breakpoints = map { $_->{Left_Breakpoint} } @pairs;
    my @right_breakpoints = map { $_->{Right_Breakpoint} } @pairs;

    my %sample_count;
    my %read_names;
    my %orientation_count;
    my %read_strand_count;
    my %mate_strand_count;

    for my $pair (@pairs) {
        $sample_count{ $pair->{Sample} }++;
        $read_names{ $pair->{Read_Name} }++;
        $orientation_count{ $pair->{Pair_Orientation} }++;
        $read_strand_count{ $pair->{Read_Strand} }++;
        $mate_strand_count{ $pair->{Mate_Strand} }++;
    }

    my @unique_reads = sort keys %read_names;

    my $cluster_start = int_median(@sv_starts);
    my $cluster_end   = int_median(@sv_ends);
    my $cluster_length = $cluster_end - $cluster_start + 1;
    $cluster_length = 0 if $cluster_length < 0;

    return {
        Cluster_ID             => "NA",
        Sample                 => join(",", sort keys %sample_count),
        SV_Chrom               => $pairs[0]->{SV_Chrom},
        Cluster_Start          => $cluster_start,
        Cluster_End            => $cluster_end,
        Cluster_Length         => $cluster_length,

        Support_Reads          => scalar(@unique_reads),
        Support_Records        => scalar(@pairs),
        Read_Names             => join(",", @unique_reads),

        SV_Start_Median        => $cluster_start,
        SV_End_Median          => $cluster_end,
        SV_Start_Min           => min_num(@sv_starts),
        SV_Start_Max           => max_num(@sv_starts),
        SV_End_Min             => min_num(@sv_ends),
        SV_End_Max             => max_num(@sv_ends),
        SV_Length_Mean         => mean_num(@sv_lengths),
        SV_Length_Min          => min_num(@sv_lengths),
        SV_Length_Max          => max_num(@sv_lengths),

        Median_Insert_Size     => median_num(@insert_sizes),
        Mean_Insert_Size       => mean_num(@insert_sizes),
        Min_Insert_Size        => min_num(@insert_sizes),
        Max_Insert_Size        => max_num(@insert_sizes),

        Left_Breakpoint_Min    => min_num(@left_breakpoints),
        Left_Breakpoint_Max    => max_num(@left_breakpoints),
        Right_Breakpoint_Min   => min_num(@right_breakpoints),
        Right_Breakpoint_Max   => max_num(@right_breakpoints),

        Pair_Orientation_Count => format_count_hash(\%orientation_count),
        Read_Strand_Count      => format_count_hash(\%read_strand_count),
        Mate_Strand_Count      => format_count_hash(\%mate_strand_count),

        Cluster_Status         => "NA",
        Cluster_Comment        => "NA",
        pairs                  => \@pairs,
    };
}

sub classify_clusters {
    my %args = @_;

    my $clusters_ref = $args{clusters_ref};
    my $min_support_reads = $args{min_support_reads};

    for my $cluster (@{$clusters_ref}) {
        if ($cluster->{Support_Reads} >= $min_support_reads) {
            $cluster->{Cluster_Status} = "Pass";
            $cluster->{Cluster_Comment} = "Support_Reads >= MIN_DISCORDANT_READS";
        } else {
            $cluster->{Cluster_Status} = "LowSupport";
            $cluster->{Cluster_Comment} = "Support_Reads < MIN_DISCORDANT_READS";
        }

        for my $pair (@{ $cluster->{pairs} }) {
            $pair->{Cluster_ID} = $cluster->{Cluster_ID};
            $pair->{Cluster_Status} = $cluster->{Cluster_Status};
        }
    }
}

# ============================================================
# Output writers
# ============================================================

sub write_cluster_summary {
    my %args = @_;

    my $clusters_ref = $args{clusters_ref};
    my $output = $args{output};
    my $mode = $args{mode};

    open my $OUT, ">", $output
        or die "[ERROR] Cannot write cluster summary output: $output\n";

    my @header = qw(
        Sample
        Cluster_ID
        SV_Chrom
        Cluster_Start
        Cluster_End
        Cluster_Length
        Support_Reads
        Support_Records
        Read_Names
        SV_Start_Median
        SV_End_Median
        SV_Start_Range
        SV_End_Range
        SV_Length_Mean
        SV_Length_Range
        Median_Insert_Size
        Mean_Insert_Size
        Insert_Size_Range
        Left_Breakpoint_Range
        Right_Breakpoint_Range
        Pair_Orientation_Count
        Read_Strand_Count
        Mate_Strand_Count
        Cluster_Status
        Cluster_Comment
    );

    print $OUT join("\t", @header), "\n";

    for my $cluster (@{$clusters_ref}) {
        if ($mode eq "Pass") {
            next unless $cluster->{Cluster_Status} eq "Pass";
        } elsif ($mode eq "Failed") {
            next if $cluster->{Cluster_Status} eq "Pass";
        } elsif ($mode eq "All") {
            # keep all clusters
        } else {
            die "[ERROR] Unknown output mode: $mode\n";
        }

        print $OUT join("\t",
            $cluster->{Sample},
            $cluster->{Cluster_ID},
            $cluster->{SV_Chrom},
            $cluster->{Cluster_Start},
            $cluster->{Cluster_End},
            $cluster->{Cluster_Length},
            $cluster->{Support_Reads},
            $cluster->{Support_Records},
            $cluster->{Read_Names},
            $cluster->{SV_Start_Median},
            $cluster->{SV_End_Median},
            $cluster->{SV_Start_Min} . "-" . $cluster->{SV_Start_Max},
            $cluster->{SV_End_Min} . "-" . $cluster->{SV_End_Max},
            sprintf("%.2f", $cluster->{SV_Length_Mean}),
            $cluster->{SV_Length_Min} . "-" . $cluster->{SV_Length_Max},
            sprintf("%.2f", $cluster->{Median_Insert_Size}),
            sprintf("%.2f", $cluster->{Mean_Insert_Size}),
            $cluster->{Min_Insert_Size} . "-" . $cluster->{Max_Insert_Size},
            $cluster->{Left_Breakpoint_Min} . "-" . $cluster->{Left_Breakpoint_Max},
            $cluster->{Right_Breakpoint_Min} . "-" . $cluster->{Right_Breakpoint_Max},
            $cluster->{Pair_Orientation_Count},
            $cluster->{Read_Strand_Count},
            $cluster->{Mate_Strand_Count},
            $cluster->{Cluster_Status},
            $cluster->{Cluster_Comment},
        ), "\n";
    }

    close $OUT;
}

sub write_supporting_pairs {
    my %args = @_;

    my $clusters_ref = $args{clusters_ref};
    my $output = $args{output};

    open my $OUT, ">", $output
        or die "[ERROR] Cannot write supporting-pair output: $output\n";

    my @header = qw(
        Sample
        Cluster_ID
        Cluster_Status
        Read_Name
        Flag
        Chrom
        Read_Start
        Read_End
        Mate_Chrom
        Mate_Start
        TLEN
        Insert_Size
        MAPQ
        CIGAR
        Read_Strand
        Mate_Strand
        Pair_Orientation
        Left_Breakpoint
        Right_Breakpoint
        SV_Chrom
        SV_Start
        SV_End
        SV_Length
        Pair_Key
    );

    print $OUT join("\t", @header), "\n";

    for my $cluster (@{$clusters_ref}) {
        for my $pair (@{ $cluster->{pairs} }) {
            my %row = %{$pair};
            $row{Cluster_ID} = $cluster->{Cluster_ID};
            $row{Cluster_Status} = $cluster->{Cluster_Status};

            print $OUT join("\t", map { defined $row{$_} ? $row{$_} : "NA" } @header), "\n";
        }
    }

    close $OUT;
}

