# ============================================================
# Config helpers
# ============================================================

sub read_config {
    my ($file) = @_;

    my %conf;

    open my $FH, "<", $file
        or die "[ERROR] Cannot open config file: $file\n";

    while (my $line = <$FH>) {
        chomp $line;
        $line =~ s/\r$//;

        next if $line =~ /^\s*$/;
        next if $line =~ /^\s*#/;

        $line =~ s/\s+#.*$//;

        next unless $line =~ /^\s*([^=\s]+)\s*=\s*(.*?)\s*$/;

        my ($key, $val) = ($1, $2);

        $key =~ s/^\s+|\s+$//g;
        $val =~ s/^\s+|\s+$//g;

        $val =~ s/^['"]//;
        $val =~ s/['"]$//;

        die "[ERROR] Empty config key found in $file\n"
            if $key eq "";

        $conf{$key} = $val;
    }

    close $FH;

    return %conf;
}

sub get_conf_required {
    my ($conf_ref, $key) = @_;

    die "[ERROR] Required config parameter missing: $key\n"
        unless exists $conf_ref->{$key}
            && defined $conf_ref->{$key}
            && $conf_ref->{$key} ne "";

    return $conf_ref->{$key};
}

# ============================================================
# Validation helpers
# ============================================================

sub validate_bool_01 {
    my ($name, $value) = @_;

    die "[ERROR] $name must be 0 or 1. Observed: $value\n"
        unless defined $value && $value =~ /^[01]$/;

    return 1;
}

sub validate_positive_integer {
    my ($name, $value) = @_;

    die "[ERROR] $name must be a positive integer. Observed: $value\n"
        unless defined $value && $value =~ /^\d+$/ && $value >= 1;

    return 1;
}

sub validate_nonnegative_integer {
    my ($name, $value) = @_;

    die "[ERROR] $name must be a non-negative integer. Observed: $value\n"
        unless defined $value && $value =~ /^\d+$/;

    return 1;
}

sub check_executable {
    my ($cmd, $name) = @_;

    die "[ERROR] Empty executable path for $name\n"
        unless defined $cmd && $cmd ne "";

    if ($cmd =~ m{/}) {
        die "[ERROR] $name executable not found or not executable: $cmd\n"
            unless -x $cmd;
    } else {
        my $ret = system("command -v $cmd >/dev/null 2>&1");
        die "[ERROR] $name executable not found in PATH: $cmd\n"
            if $ret != 0;
    }

    return 1;
}

sub check_bam_index {
    my ($bam_file) = @_;

    my $bai1 = "$bam_file.bai";

    my $bai2 = $bam_file;
    $bai2 =~ s/\.bam$/.bai/i;

    die "[ERROR] BAM index not found for: $bam_file\n"
      . "        Expected one of:\n"
      . "        $bai1\n"
      . "        $bai2\n"
        unless -s $bai1 || -s $bai2;

    return 1;
}

# ============================================================
# SAM / BAM helpers
# ============================================================

sub cigar_ref_length {
    my ($cigar) = @_;

    return 0
        unless defined $cigar
            && $cigar ne ""
            && $cigar ne "*";

    my $len = 0;

    while ($cigar =~ /(\d+)([MIDNSHP=X])/g) {
        my ($n, $op) = ($1, $2);

        # Operations consuming reference:
        # M, D, N, =, X
        if ($op =~ /^[MDN=X]$/) {
            $len += $n;
        }
    }

    return $len;
}

sub get_pair_orientation {
    my ($flag) = @_;

    my $read = is_reverse($flag) ? "R" : "F";
    my $mate = is_mate_reverse($flag) ? "R" : "F";

    return $read . $mate;
}

sub is_deletion_like_orientation {
    my ($flag) = @_;

    # With TLEN > 0 retained, the current read is expected to be
    # the leftmost segment. Deletion-like paired-end support is
    # left read forward and right mate reverse.
    return (!is_reverse($flag) && is_mate_reverse($flag)) ? 1 : 0;
}

# ------------------------------------------------------------
# SAM flag helpers
# ------------------------------------------------------------
sub is_paired {
    return ($_[0] & 0x1) ? 1 : 0;
}

sub is_unmapped {
    return ($_[0] & 0x4) ? 1 : 0;
}

sub is_mate_unmapped {
    return ($_[0] & 0x8) ? 1 : 0;
}

sub is_reverse {
    return ($_[0] & 0x10) ? 1 : 0;
}

sub is_mate_reverse {
    return ($_[0] & 0x20) ? 1 : 0;
}

sub is_secondary {
    return ($_[0] & 0x100) ? 1 : 0;
}

sub is_duplicate {
    return ($_[0] & 0x400) ? 1 : 0;
}

sub is_supplementary {
    return ($_[0] & 0x800) ? 1 : 0;
}

# ============================================================
# Numeric helpers
# ============================================================

sub int_median {
    my @values = sort { $a <=> $b } @_;

    return 0 unless @values;

    my $n = scalar(@values);

    if ($n % 2) {
        return int($values[int($n / 2)] + 0.5);
    }

    return int(($values[$n / 2 - 1] + $values[$n / 2]) / 2 + 0.5);
}

sub median_num {
    my @values = sort { $a <=> $b } @_;

    return 0 unless @values;

    my $n = scalar(@values);

    if ($n % 2) {
        return $values[int($n / 2)];
    }

    return ($values[$n / 2 - 1] + $values[$n / 2]) / 2;
}

sub mean_num {
    my @values = @_;

    return 0 unless @values;

    my $sum = 0;
    $sum += $_ for @values;

    return $sum / scalar(@values);
}

sub min_num {
    my @values = @_;

    die "[ERROR] min_num called with empty list\n"
        unless @values;

    my $min = $values[0];

    for my $v (@values) {
        $min = $v if $v < $min;
    }

    return $min;
}

sub max_num {
    my @values = @_;

    die "[ERROR] max_num called with empty list\n"
        unless @values;

    my $max = $values[0];

    for my $v (@values) {
        $max = $v if $v > $max;
    }

    return $max;
}

sub format_count_hash {
    my ($hash_ref) = @_;

    return "NA" unless %{$hash_ref};

    return join(",", map { $_ . ":" . $hash_ref->{$_} } sort keys %{$hash_ref});
}

sub chrom_order_key {
    my ($chr) = @_;

    my $x = $chr;
    $x =~ s/^chr//i;

    return sprintf("%03d", $x) if $x =~ /^\d+$/;

    my $u = uc($x);

    return "023" if $u eq "X";
    return "024" if $u eq "Y";
    return "025" if $u eq "M" || $u eq "MT";

    return "999_$chr";
}

sub shell_quote {
    my ($str) = @_;

    die "[ERROR] Undefined shell argument\n"
        unless defined $str;

    return "''" if $str eq "";

    return $str
        if $str =~ /^[A-Za-z0-9_\.\-\/\:=,\+]+$/;

    $str =~ s/'/'\\''/g;

    return "'$str'";
}

sub usage {
    return <<'USAGE';
Usage:
  perl bin/run_discordant_reads.pl \
    --config /abs/path/conf/hcm_exondel.conf \
    --bam /abs/path/SAMPLE.target.bam \
    --sample SAMPLE_ID \
    --out /abs/path/results/SAMPLE/03.discordant_reads/SAMPLE.discordant_reads.tsv

Required arguments:
  --config / --conf
      HCMExonDel config file.

  --bam
      Coordinate-sorted and indexed target BAM generated by extract_target_bam.pl.

  --sample
      Sample ID.

  --out
      PASS discordant cluster summary output.

Required config parameters:
  SAMTOOLS
  MIN_MAPQ
  EXCLUDE_DUPLICATES
  MIN_DISCORDANT_INSERT_SIZE
  MIN_DISCORDANT_READS
  DISCORDANT_CLUSTER_DISTANCE
  FILTER_DELETION_ORIENTATION
  DISCORDANT_READ_THREADS

Outputs:
  --out
      PASS discordant clusters only.

  Derived files:
      *.all_clusters.tsv
      *.failed_clusters.tsv
      *.supporting_pairs.tsv
      *.raw_pairs.tsv

Notes:
  1. Input BAM must be SAMPLE.target.bam, not the original WGS BAM.
  2. This script scans the whole target BAM directly.
  3. Gene and exon annotation should be performed later by annotate_candidates.pl.
USAGE
}

